/** Adds ids to draw edges via -keyword-links.json  files instead keywords are anonymized*/ 
export function slugify(title, used, fallbackIndex) {
  const base =
    title
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .slice(0, 60) || `paper-${fallbackIndex}`;
  let slug = base;
  let i = 2;
  while (used.has(slug)) {
    slug = `${base}-${i}`;
    i += 1;
  }
  used.add(slug);
  return slug;
}

export function assignPaperIds(records) {
  const used = new Set();
  return records.map((record, i) => ({
    ...record,
    _id: slugify(record.metadata?.title || '', used, i),
  }));
}
